local LaceMaker = {}
local PRODUCTS = {
    simple_bobbin_lace = { name = "Preprosta čipka iz kobilic", linenCost = 2, woodCost = 1, time = 3, cost = 35, beauty = 18, happiness = 1, description = "Preprosta čipka iz kobilic za obrobe." },
    torchon_lace_strip = { name = "Trak navadne čipke", linenCost = 3, woodCost = 1, time = 6, cost = 110, beauty = 35, happiness = 1, prestige = 2, description = "Trak navadne čipke za oblačila." },
    brussels_lace_collar = { name = "Bruseljski čipkasti ovratnik", linenCost = 3, silkCost = 1, woodCost = 1, time = 9, cost = 280, beauty = 50, happiness = 2, prestige = 6, description = "Bruseljski čipkasti ovratnik za plemiče." },
    silver_thread_lace = { name = "Srebrnonitna čipka", linenCost = 3, silkCost = 2, silverCost = 1, woodCost = 1, time = 13, cost = 680, beauty = 65, happiness = 3, prestige = 14, description = "Srebrnonitna čipka za visoke plemiče." },
    gold_edged_venetian_lace = { name = "Zlato obrobljena beneška čipka", linenCost = 4, silkCost = 2, goldCost = 1, silverCost = 1, woodCost = 1, time = 17, cost = 1500, beauty = 78, happiness = 5, prestige = 26, description = "Beneška čipka z zlato obrobo za visoko plemstvo." },
    royal_point_venise_lace = { name = "Kraljevska beneška točkasta čipka", linenCost = 6, silkCost = 4, goldCost = 2, silverCost = 2, jewelCost = 1, pearlCost = 1, time = 24, cost = 3700, beauty = 92, happiness = 12, prestige = 58, description = "Velika kraljevska beneška čipka z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    lace_workshop = { name = "Čipkarska delavnica", cost = { gold = 220, wood = 100, stone = 80, linen = 6 }, upkeep = 5, qualityBonus = 5 },
    bobbin_loft = { name = "Kobilna podstrešje", cost = { gold = 800, wood = 240, stone = 220, silk = 6, wood = 8 }, upkeep = 18, qualityBonus = 18 },
    venetian_atelier = { name = "Beneški atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_lace_palace = { name = "Kraljevska čipkarska palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
LaceMaker.linenStock = 16; LaceMaker.silkStock = 12; LaceMaker.woodStock = 10; LaceMaker.silverStock = 6; LaceMaker.goldStock = 6; LaceMaker.jewelStock = 4; LaceMaker.pearlStock = 4
LaceMaker.productStock = {}; LaceMaker.buildings = {}; LaceMaker.maker = nil; LaceMaker.activeMaking = {}; LaceMaker.totalProducts = 0; LaceMaker.dayTimer = 0
function LaceMaker.init() LaceMaker.linenStock=16; LaceMaker.silkStock=12; LaceMaker.woodStock=10; LaceMaker.silverStock=6; LaceMaker.goldStock=6; LaceMaker.jewelStock=4; LaceMaker.pearlStock=4; LaceMaker.productStock={}; LaceMaker.buildings={}; LaceMaker.maker=nil; LaceMaker.activeMaking={}; LaceMaker.totalProducts=0; LaceMaker.dayTimer=0; print("[LaceMaker] Royal Lace Maker System initialized (6 products, 4 buildings)") end
function LaceMaker.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LaceMaker.maker={name=n or ("Čipkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čipkar najet: %s (spretnost: %d)",LaceMaker.maker.name,s),"success") end; return true end
function LaceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LaceMaker.build(id) local ok,e=LaceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LaceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LaceMaker.getQualityBonus() local b=0; for _,bd in ipairs(LaceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LaceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.linenCost and LaceMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.silkCost and LaceMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.woodCost and LaceMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and LaceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LaceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LaceMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LaceMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LaceMaker.buildings==0 then return false,"Potrebna čipkarska delavnica" end; if not LaceMaker.maker then return false,"Potreben čipkar" end; return true end
function LaceMaker.make(pt,qty) qty=qty or 1; local ok,e=LaceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.linenCost then LaceMaker.linenStock=LaceMaker.linenStock-d.linenCost*qty end; if d.silkCost then LaceMaker.silkStock=LaceMaker.silkStock-d.silkCost*qty end; if d.woodCost then LaceMaker.woodStock=LaceMaker.woodStock-d.woodCost*qty end; if d.silverCost then LaceMaker.silverStock=LaceMaker.silverStock-d.silverCost*qty end; if d.goldCost then LaceMaker.goldStock=LaceMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LaceMaker.jewelStock=LaceMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LaceMaker.pearlStock=LaceMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LaceMaker.maker then t=math.max(1,t-math.floor(LaceMaker.maker.skill/13)) end; table.insert(LaceMaker.activeMaking,{id="lace_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezava čipke: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LaceMaker.completeMaking(m) local q=1.0+(LaceMaker.getQualityBonus()/100); if LaceMaker.maker then q=q+(LaceMaker.maker.skill/150) end; q=math.min(2.4,q); LaceMaker.productStock[m.productType]=(LaceMaker.productStock[m.productType] or 0)+m.quantity; LaceMaker.totalProducts=LaceMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LaceMaker.maker then LaceMaker.maker.itemsMade=LaceMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LaceMaker.maker.skill=math.min(100,LaceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čipka gotova: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"lace.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function LaceMaker.update(dt) if not _G.state then return end; LaceMaker.dayTimer=LaceMaker.dayTimer+dt; if LaceMaker.dayTimer>=30 then LaceMaker.dayTimer=0; for i=#LaceMaker.activeMaking,1,-1 do local m=LaceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LaceMaker.completeMaking(m); table.remove(LaceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LaceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LaceMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LaceMaker.getStats() return {linenStock=LaceMaker.linenStock,silkStock=LaceMaker.silkStock,woodStock=LaceMaker.woodStock,silverStock=LaceMaker.silverStock,goldStock=LaceMaker.goldStock,jewelStock=LaceMaker.jewelStock,pearlStock=LaceMaker.pearlStock,productStock=LaceMaker.productStock,numBuildings=#LaceMaker.buildings,hasMaker=LaceMaker.maker~=nil,makerName=LaceMaker.maker and LaceMaker.maker.name or "—",makerSkill=LaceMaker.maker and LaceMaker.maker.skill or 0,activeMaking=#LaceMaker.activeMaking,totalProducts=LaceMaker.totalProducts} end
return LaceMaker
